def solve(s: str) -> int:
    """Return the length of the longest substring without repeating characters.
    Sliding window using a dictionary to store the last index of each character.
    """
    left = 0
    max_len = 0
    last_seen = {}
    for right, ch in enumerate(s):
        if ch in last_seen and last_seen[ch] >= left:
            left = last_seen[ch] + 1
        last_seen[ch] = right
        cur_len = right - left + 1
        if cur_len > max_len:
            max_len = cur_len
    return max_len

