def solve(path: str) -> str:
    # reference using pathlib for Unix style; however PurePosixPath resolves '.' and '..' but also removes trailing slash.
    from pathlib import PurePosixPath
    # Ensure it's absolute
    if not path.startswith('/'):
        return ''
    p = PurePosixPath(path).resolve()
