def solve(s) -> int:
    """Return the length of the longest substring without repeating characters.

    The function is tolerant: if *s* is not a string (or bytes), it returns 0.
    It works for empty inputs and runs in O(n) time.
    """
    # Accept only str or bytes; otherwise treat as empty.
    if not isinstance(s, (str, bytes)):
        return 0
    if not s:
        return 0
    last_index = {}
    max_len = 0
    start = 0
    for i, ch in enumerate(s):
        prev = last_index.get(ch)
        if prev is not None and prev >= start:
            start = prev + 1
        last_index[ch] = i
        cur_len = i - start + 1
        if cur_len > max_len:
            max_len = cur_len
    return max_len

