def solve(s) -> int:
    """Return length of longest substring without repeating characters.
    Handles any input convertible to string.
    """
    # Ensure we work with a string
    if not isinstance(s, str):
        s = str(s)
    last_index = {}
    max_len = 0
    start = 0
    for i, ch in enumerate(s):
        prev = last_index.get(ch)
        if prev is not None and prev >= start:
            start = prev + 1
        last_index[ch] = i
        cur_len = i - start + 1
        if cur_len > max_len:
            max_len = cur_len
    return max_len

