def solve(n, edges):
    # adjacency list using set to avoid duplicate edges
    adj = [set() for _ in range(n)]
    indeg = [0]*n
    for a,b in edges:
        if 0 <= a < n and 0 <= b < n:
            if b not in adj[a]:
                adj[a].add(b)
                indeg[b] += 1
    heap = [i for i in range(n) if indeg[i]==0]
    heapq.heapify(heap)
    order = []
    while heap:
        u = heapq.heappop(heap)
        order.append(u)
        for v in sorted(adj[u]):
            indeg[v] -= 1
            if indeg[v]==0:
                heapq.heappush(heap, v)
    if len(order)!=n:
        return []
    return order
