def solve(s: str) -> bool:
    """Validate an IPv4 address.

    An IPv4 address consists of exactly four decimal numbers separated by dots.
    Each number must be in the range 0‑255 inclusive. Leading zeros are not
    allowed unless the number is exactly ``0``. No extra whitespace is permitted.
    """
    # Input must be a string.
    if not isinstance(s, str):
        return False
    parts = s.split('.')
    if len(parts) != 4:
        return False
    for part in parts:
        # Each part must be non‑empty and consist only of digits.
        if not part or not part.isdigit():
            return False
        # No leading zeros unless the part is exactly "0".
        if len(part) > 1 and part[0] == '0':
            return False
        # Convert to int and check range.
        try:
            value = int(part)
        except ValueError:
            return False
        if not (0 <= value <= 255):
            return False
    return True

